import React, { useState, useRef, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Stage, Layer, Image as KonvaImage, Circle, Rect, Line, Text } from 'react-konva';
import { useImage } from 'react-konva';
import { 
  Wifi, Router, Zap, Wind, Package, Cable, WifiOff, AlertTriangle,
  Upload, ZoomIn, ZoomOut, Move, Trash2, Save, Download, Settings,
  ChevronLeft, Plus, X, Check, AlertCircle
} from 'lucide-react';

const FloorPlanEditor = () => {
  const { propertyId, buildingId, floorId } = useParams();
  const navigate = useNavigate();
  const fileInputRef = useRef(null);
  const stageRef = useRef(null);

  const [floorPlanImage, setFloorPlanImage] = useState(null);
  const [markers, setMarkers] = useState([]);
  const [selectedMarker, setSelectedMarker] = useState(null);
  const [selectedTool, setSelectedTool] = useState('select');
  const [scale, setScale] = useState(1);
  const [isDragging, setIsDragging] = useState(false);
  const [stagePos, setStagePos] = useState({ x: 0, y: 0 });
  const [showProperties, setShowProperties] = useState(true);
  const [showTools, setShowTools] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [savedStatus, setSavedStatus] = useState('saved');

  // Marker types configuration
  const markerTypes = {
    'access-point': { icon: Wifi, color: '#3B82F6', glow: '#60A5FA', name: 'Access Point' },
    'router': { icon: Router, color: '#10B981', glow: '#34D399', name: 'Router' },
    'power': { icon: Zap, color: '#F59E0B', glow: '#FCD34D', name: 'Power Source' },
    'cooling': { icon: Wind, color: '#06B6D4', glow: '#67E8F9', name: 'Cooling Unit' },
    'rack': { icon: Package, color: '#8B5CF6', glow: '#A78BFA', name: 'Rack/Cabinet' },
    'cable': { icon: Cable, color: '#EC4899', glow: '#F472B6', name: 'Cable Entry' },
    'weak-signal': { icon: WifiOff, color: '#EF4444', glow: '#F87171', name: 'Weak Signal Area' },
    'obstruction': { icon: AlertTriangle, color: '#F97316', glow: '#FB923C', name: 'Obstruction' }
  };

  // Handle floor plan upload
  const handleFloorPlanUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      setIsLoading(true);
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new window.Image();
        img.onload = () => {
          setFloorPlanImage(img);
          setIsLoading(false);
          setSavedStatus('unsaved');
        };
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);
    }
  };

  // Add marker to canvas
  const handleCanvasClick = (e) => {
    if (selectedTool === 'select') return;

    const stage = e.target.getStage();
    const point = stage.getPointerPosition();

    const newMarker = {
      id: Date.now(),
      type: selectedTool,
      x: point.x,
      y: point.y,
      notes: '',
      priority: 'medium',
      signalStrength: 75,
      powerAvailable: true
    };

    setMarkers([...markers, newMarker]);
    setSelectedMarker(newMarker);
    setSavedStatus('unsaved');
  };

  // Handle marker drag
  const handleMarkerDragEnd = (e, markerId) => {
    const updatedMarkers = markers.map(marker => {
      if (marker.id === markerId) {
        return {
          ...marker,
          x: e.target.x(),
          y: e.target.y()
        };
      }
      return marker;
    });
    setMarkers(updatedMarkers);
    setSavedStatus('unsaved');
  };

  // Delete marker
  const deleteMarker = (markerId) => {
    setMarkers(markers.filter(m => m.id !== markerId));
    setSelectedMarker(null);
    setSavedStatus('unsaved');
  };

  // Update marker properties
  const updateMarker = (markerId, updates) => {
    const updatedMarkers = markers.map(marker => {
      if (marker.id === markerId) {
        return { ...marker, ...updates };
      }
      return marker;
    });
    setMarkers(updatedMarkers);
    setSavedStatus('unsaved');
  };

  // Zoom controls
  const handleZoomIn = () => setScale(Math.min(scale * 1.2, 5));
  const handleZoomOut = () => setScale(Math.max(scale / 1.2, 0.5));
  const handleResetZoom = () => {
    setScale(1);
    setStagePos({ x: 0, y: 0 });
  };

  // Save floor plan
  const handleSave = async () => {
    setIsLoading(true);
    // TODO: Save to backend
    await new Promise(resolve => setTimeout(resolve, 1000));
    setSavedStatus('saved');
    setIsLoading(false);
  };

  // Export floor plan
  const handleExport = () => {
    const dataStr = JSON.stringify({
      propertyId,
      buildingId,
      floorId,
      markers,
      timestamp: new Date().toISOString()
    }, null, 2);

    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
    const exportFileDefaultName = `floor-plan-${propertyId}-${buildingId}-${floorId}.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 overflow-hidden">
      {/* Header */}
      <div className="h-16 bg-black/20 backdrop-blur-xl border-b border-white/10 flex items-center justify-between px-6">
        <div className="flex items-center space-x-4">
          <button
            onClick={() => navigate('/dashboard')}
            className="p-2 rounded-lg bg-white/10 hover:bg-white/20 transition-all duration-200 text-white"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-xl font-semibold text-white">Floor Plan Editor</h1>
            <p className="text-sm text-white/60">Property {propertyId} • Building {buildingId} • Floor {floorId}</p>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          <div className="flex items-center space-x-2 px-3 py-1.5 rounded-full bg-white/10 backdrop-blur-sm">
            <div className={`w-2 h-2 rounded-full ${savedStatus === 'saved' ? 'bg-green-400' : 'bg-yellow-400'} animate-pulse`} />
            <span className="text-sm text-white/80 capitalize">{savedStatus}</span>
          </div>

          <button
            onClick={handleSave}
            disabled={isLoading}
            className="px-4 py-2 bg-blue-500 hover:bg-blue-600 disabled:opacity-50 rounded-lg flex items-center space-x-2 text-white transition-all duration-200"
          >
            <Save className="w-4 h-4" />
            <span>{isLoading ? 'Saving...' : 'Save'}</span>
          </button>

          <button
            onClick={handleExport}
            className="px-4 py-2 bg-purple-500 hover:bg-purple-600 rounded-lg flex items-center space-x-2 text-white transition-all duration-200"
          >
            <Download className="w-4 h-4" />
            <span>Export</span>
          </button>
        </div>
      </div>

      <div className="flex h-[calc(100vh-4rem)]">
        {/* Left Sidebar - Tools */}
        <AnimatePresence>
          {showTools && (
            <motion.div
              initial={{ x: -300 }}
              animate={{ x: 0 }}
              exit={{ x: -300 }}
              className="w-20 bg-black/20 backdrop-blur-xl border-r border-white/10 p-4 flex flex-col space-y-3"
            >
              <button
                onClick={() => setSelectedTool('select')}
                className={`p-3 rounded-lg transition-all duration-200 ${
                  selectedTool === 'select' 
                    ? 'bg-blue-500 text-white shadow-lg shadow-blue-500/50' 
                    : 'bg-white/10 text-white/70 hover:bg-white/20 hover:text-white'
                }`}
              >
                <Move className="w-5 h-5" />
              </button>

              <div className="h-px bg-white/10" />

              {Object.entries(markerTypes).map(([type, config]) => {
                const Icon = config.icon;
                return (
                  <button
                    key={type}
                    onClick={() => setSelectedTool(type)}
                    className={`p-3 rounded-lg transition-all duration-200 group relative ${
                      selectedTool === type 
                        ? 'bg-white/20 text-white shadow-lg' 
                        : 'bg-white/10 text-white/70 hover:bg-white/20 hover:text-white'
                    }`}
                    title={config.name}
                  >
                    <Icon className="w-5 h-5" />
                    <div className="absolute inset-0 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity duration-200"
                         style={{ boxShadow: `0 0 20px ${config.glow}` }} />
                  </button>
                );
              })}

              <div className="flex-1" />

              {!floorPlanImage && (
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="p-3 rounded-lg bg-green-500/20 text-green-400 hover:bg-green-500/30 transition-all duration-200"
                  title="Upload Floor Plan"
                >
                  <Upload className="w-5 h-5" />
                </button>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Main Canvas Area */}
        <div className="flex-1 relative bg-black/30">
          {/* Zoom Controls */}
          <div className="absolute top-4 right-4 flex flex-col space-y-2 z-10">
            <button
              onClick={handleZoomIn}
              className="p-2 rounded-lg bg-white/10 backdrop-blur-sm text-white hover:bg-white/20 transition-all duration-200"
            >
              <ZoomIn className="w-4 h-4" />
            </button>
            <button
              onClick={handleZoomOut}
              className="p-2 rounded-lg bg-white/10 backdrop-blur-sm text-white hover:bg-white/20 transition-all duration-200"
            >
              <ZoomOut className="w-4 h-4" />
            </button>
            <button
              onClick={handleResetZoom}
              className="p-2 rounded-lg bg-white/10 backdrop-blur-sm text-white hover:bg-white/20 transition-all duration-200"
            >
              <span className="text-xs">100%</span>
            </button>
          </div>

          {/* Canvas */}
          <div className="w-full h-full flex items-center justify-center">
            {!floorPlanImage ? (
              <div className="text-center">
                <div className="w-32 h-32 mx-auto mb-6 rounded-2xl bg-gradient-to-br from-blue-500/20 to-purple-500/20 flex items-center justify-center">
                  <Upload className="w-16 h-16 text-white/50" />
                </div>
                <h3 className="text-xl font-semibold text-white mb-2">Upload Floor Plan</h3>
                <p className="text-white/60 mb-6">Upload a JPG, PNG, or PDF file to get started</p>
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="px-6 py-3 bg-gradient-to-r from-blue-500 to-purple-500 rounded-lg text-white font-medium hover:from-blue-600 hover:to-purple-600 transition-all duration-200"
                >
                  Choose File
                </button>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*,.pdf"
                  onChange={handleFloorPlanUpload}
                  className="hidden"
                />
              </div>
            ) : (
              <Stage
                ref={stageRef}
                width={window.innerWidth - (showTools ? 320 : 160)}
                height={window.innerHeight - 160}
                scaleX={scale}
                scaleY={scale}
                x={stagePos.x}
                y={stagePos.y}
                onWheel={(e) => {
                  e.evt.preventDefault();
                  const scaleBy = 1.1;
                  const stage = e.target.getStage();
                  const oldScale = stage.scaleX();
                  const pointer = stage.getPointerPosition();

                  const mousePointTo = {
                    x: pointer.x / oldScale - stage.x() / oldScale,
                    y: pointer.y / oldScale - stage.y() / oldScale,
                  };

                  const newScale = e.evt.deltaY > 0 ? oldScale / scaleBy : oldScale * scaleBy;

                  setScale(Math.min(Math.max(newScale, 0.5), 5));
                }}
                onClick={handleCanvasClick}
              >
                <Layer>
                  {/* Floor Plan Image */}
                  <KonvaImage
                    image={floorPlanImage}
                    width={floorPlanImage.width}
                    height={floorPlanImage.height}
                  />

                  {/* Markers */}
                  {markers.map((marker) => {
                    const config = markerTypes[marker.type];
                    const isSelected = selectedMarker?.id === marker.id;

                    return (
                      <React.Fragment key={marker.id}>
                        {/* Glow Effect */}
                        <Circle
                          x={marker.x}
                          y={marker.y}
                          radius={isSelected ? 25 : 20}
                          fill={config.glow}
                          opacity={0.3}
                          shadowBlur={isSelected ? 20 : 10}
                          shadowColor={config.glow}
                        />

                        {/* Main Marker */}
                        <Circle
                          x={marker.x}
                          y={marker.y}
                          radius={12}
                          fill={config.color}
                          stroke={isSelected ? '#fff' : 'transparent'}
                          strokeWidth={isSelected ? 2 : 0}
                          draggable={selectedTool === 'select'}
                          onDragEnd={(e) => handleMarkerDragEnd(e, marker.id)}
                          onClick={(e) => {
                            e.cancelBubble = true;
                            setSelectedMarker(marker);
                          }}
                        />

                        {/* Status Indicator */}
                        {marker.powerAvailable && (
                          <Circle
                            x={marker.x + 8}
                            y={marker.y - 8}
                            radius={4}
                            fill="#10B981"
                          />
                        )}
                      </React.Fragment>
                    );
                  })}
                </Layer>
              </Stage>
            )}
          </div>
        </div>

        {/* Right Sidebar - Properties */}
        <AnimatePresence>
          {showProperties && selectedMarker && (
            <motion.div
              initial={{ x: 300 }}
              animate={{ x: 0 }}
              exit={{ x: 300 }}
              className="w-80 bg-black/20 backdrop-blur-xl border-l border-white/10 p-6 overflow-y-auto"
            >
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-lg font-semibold text-white">Marker Properties</h3>
                <button
                  onClick={() => setSelectedMarker(null)}
                  className="p-1 rounded-lg text-white/60 hover:text-white hover:bg-white/10"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              {selectedMarker && (
                <div className="space-y-4">
                  {/* Marker Type */}
                  <div>
                    <label className="block text-sm font-medium text-white/80 mb-2">Type</label>
                    <div className="flex items-center space-x-3 p-3 rounded-lg bg-white/10">
                      <div className="w-8 h-8 rounded-lg flex items-center justify-center"
                           style={{ backgroundColor: markerTypes[selectedMarker.type].color }}>
                        {React.createElement(markerTypes[selectedMarker.type].icon, { 
                          className: 'w-4 h-4 text-white' 
                        })}
                      </div>
                      <span className="text-white">{markerTypes[selectedMarker.type].name}</span>
                    </div>
                  </div>

                  {/* Priority */}
                  <div>
                    <label className="block text-sm font-medium text-white/80 mb-2">Priority</label>
                    <select
                      value={selectedMarker.priority}
                      onChange={(e) => updateMarker(selectedMarker.id, { priority: e.target.value })}
                      className="w-full px-3 py-2 rounded-lg bg-white/10 text-white border border-white/20 focus:border-blue-400 focus:outline-none"
                    >
                      <option value="low">Low</option>
                      <option value="medium">Medium</option>
                      <option value="high">High</option>
                    </select>
                  </div>

                  {/* Signal Strength */}
                  <div>
                    <label className="block text-sm font-medium text-white/80 mb-2">
                      Signal Strength: {selectedMarker.signalStrength}%
                    </label>
                    <input
                      type="range"
                      min="0"
                      max="100"
                      value={selectedMarker.signalStrength}
                      onChange={(e) => updateMarker(selectedMarker.id, { signalStrength: parseInt(e.target.value) })}
                      className="w-full"
                    />
                  </div>

                  {/* Power Available */}
                  <div>
                    <label className="flex items-center space-x-3 text-white/80">
                      <input
                        type="checkbox"
                        checked={selectedMarker.powerAvailable}
                        onChange={(e) => updateMarker(selectedMarker.id, { powerAvailable: e.target.checked })}
                        className="w-4 h-4 rounded"
                      />
                      <span>Power Available</span>
                    </label>
                  </div>

                  {/* Notes */}
                  <div>
                    <label className="block text-sm font-medium text-white/80 mb-2">Notes</label>
                    <textarea
                      value={selectedMarker.notes}
                      onChange={(e) => updateMarker(selectedMarker.id, { notes: e.target.value })}
                      rows={4}
                      className="w-full px-3 py-2 rounded-lg bg-white/10 text-white border border-white/20 focus:border-blue-400 focus:outline-none resize-none"
                      placeholder="Add notes..."
                    />
                  </div>

                  {/* Delete Button */}
                  <button
                    onClick={() => deleteMarker(selectedMarker.id)}
                    className="w-full px-4 py-2 bg-red-500 hover:bg-red-600 rounded-lg flex items-center justify-center space-x-2 text-white transition-all duration-200"
                  >
                    <Trash2 className="w-4 h-4" />
                    <span>Delete Marker</span>
                  </button>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default FloorPlanEditor;
